"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[7988],{47583:e=>{e.exports=JSON.parse('{"functions":[{"name":"Get","desc":"","params":[{"name":"id","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"GroundSpawn?\\n"}],"function_type":"method","source":{"line":265,"path":"src2/server/EmberServerLibrary/GameServer/Services/GroundItemService.service.luau"}},{"name":"GetSpawnsInCell","desc":"Every pile in the cell containing `position`.\\n\\nReturns the live bucket\'s contents copied out, so a caller may remove piles\\nwhile iterating.","params":[{"name":"position","desc":"","lua_type":"Vector3"}],"returns":[{"desc":"","lua_type":"{ GroundSpawn }\\n"}],"function_type":"method","source":{"line":277,"path":"src2/server/EmberServerLibrary/GameServer/Services/GroundItemService.service.luau"}},{"name":"GetSpawnsInRadius","desc":"Every pile within `radius` studs of `position`.\\n\\nWalks the cells the sphere touches rather than every pile in the world. At\\nthe default interaction radius that is a handful of buckets.","params":[{"name":"position","desc":"","lua_type":"Vector3"},{"name":"radius","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"{ GroundSpawn }\\n"}],"function_type":"method","source":{"line":290,"path":"src2/server/EmberServerLibrary/GameServer/Services/GroundItemService.service.luau"}},{"name":"FindMergeable","desc":"A pile in the same cell that `stack` could merge into.\\n\\nMerge eligibility is `HolderService:AreMergeable`, which compares durability\\nand skin as well as class. The old service compared `ClassName` alone and\\nadditionally refused to merge anything whose `MaxQuantity` was 1, so a\\ndamaged rifle could absorb a pristine one. This is stricter, and it is the\\nrule the rest of the model already uses -- see the merge-strictness open\\nquestion in `src2/PORT.md`.","params":[{"name":"stack","desc":"","lua_type":"ItemStack"},{"name":"position","desc":"","lua_type":"Vector3"}],"returns":[{"desc":"","lua_type":"GroundSpawn?\\n"}],"function_type":"method","source":{"line":329,"path":"src2/server/EmberServerLibrary/GameServer/Services/GroundItemService.service.luau"}},{"name":"IsInRange","desc":"Whether `player` is close enough to interact with `spawn`.\\n\\nReads the character fresh; a cached position went stale across a respawn.","params":[{"name":"spawn","desc":"","lua_type":"GroundSpawn"},{"name":"player","desc":"","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"method","source":{"line":352,"path":"src2/server/EmberServerLibrary/GameServer/Services/GroundItemService.service.luau"}},{"name":"Place","desc":"Put an existing ground holder into the world at `cframe`.\\n\\nThe holder must already hold a stack. Use this when something has produced a\\npile and needs it placed -- `InventoryService:Drop` returns exactly that.","params":[{"name":"holder","desc":"","lua_type":"ItemHolder"},{"name":"cframe","desc":"","lua_type":"CFrame"},{"name":"options","desc":"","lua_type":"DropOptions?\\n"}],"returns":[{"desc":"","lua_type":"GroundSpawn?\\n"}],"function_type":"method","source":{"line":371,"path":"src2/server/EmberServerLibrary/GameServer/Services/GroundItemService.service.luau"}},{"name":"PlaceStack","desc":"Place a loose stack, with no source holder.\\n\\nThis is how a spawner, a loot table or an NPC death drop puts something on\\nthe ground: there is no holder it is coming out of, so one is created for it.","params":[{"name":"stack","desc":"","lua_type":"ItemStack"},{"name":"cframe","desc":"","lua_type":"CFrame"},{"name":"options","desc":"","lua_type":"DropOptions?\\n"}],"returns":[{"desc":"","lua_type":"GroundSpawn?\\n"}],"function_type":"method","source":{"line":468,"path":"src2/server/EmberServerLibrary/GameServer/Services/GroundItemService.service.luau"}},{"name":"Drop","desc":"Drop `quantity` out of `holder` onto the ground.\\n\\n`holder` is wherever the quantity is coming from -- an inventory slot, an\\nequipment slot, another pile. It is NOT emptied unless the whole stack moves,\\nand it is never cleared as a side effect: an emptied slot is just an empty\\nslot, and the caller does not have to know which of those happened.\\n\\nReturns the pile the quantity landed in, which may be one that already\\nexisted.","params":[{"name":"holder","desc":"","lua_type":"ItemHolder"},{"name":"cframe","desc":"","lua_type":"CFrame"},{"name":"quantity","desc":"","lua_type":"number?"},{"name":"options","desc":"","lua_type":"DropOptions?\\n"}],"returns":[{"desc":"","lua_type":"GroundSpawn?\\n"}],"function_type":"method","source":{"line":493,"path":"src2/server/EmberServerLibrary/GameServer/Services/GroundItemService.service.luau"}},{"name":"Take","desc":"Move quantity from a pile into an inventory.\\n\\nReturns what actually moved. A pile that empties is removed; one that does\\nnot is left exactly as it is, holding the remainder -- which is the case the\\nold model could not express, because the thing holding the excess was the\\nitem being taken.","params":[{"name":"spawn","desc":"","lua_type":"GroundSpawn"},{"name":"inventory","desc":"","lua_type":"Inventory"},{"name":"quantity","desc":"","lua_type":"number?\\n"}],"returns":[{"desc":"","lua_type":"TransferResult\\n"}],"function_type":"method","source":{"line":543,"path":"src2/server/EmberServerLibrary/GameServer/Services/GroundItemService.service.luau"}},{"name":"TakeFor","desc":"`Take`, gated on the player being close enough.\\n\\nThe range check lives here rather than at the call site because it is the\\nauthority check: a client asking to pick something up is not trusted about\\nwhere it is standing.","params":[{"name":"spawn","desc":"","lua_type":"GroundSpawn"},{"name":"player","desc":"","lua_type":"Player"},{"name":"inventory","desc":"","lua_type":"Inventory"},{"name":"quantity","desc":"","lua_type":"number?\\n"}],"returns":[{"desc":"","lua_type":"TransferResult\\n"}],"function_type":"method","source":{"line":574,"path":"src2/server/EmberServerLibrary/GameServer/Services/GroundItemService.service.luau"}},{"name":"Remove","desc":"Take a pile out of the world.\\n\\nThe stack it holds is NOT destroyed -- the holder is handed back, so a caller\\nthat is moving a pile somewhere else keeps what was in it. Piles that expire\\nor are cleared simply drop the reference, which is what destruction means for\\ndata that owns no identity.","params":[{"name":"spawn","desc":"","lua_type":"GroundSpawn"}],"returns":[{"desc":"","lua_type":"ItemHolder\\n"}],"function_type":"method","source":{"line":599,"path":"src2/server/EmberServerLibrary/GameServer/Services/GroundItemService.service.luau"}},{"name":"RemoveBySpawner","desc":"Remove every pile a given spawner owns, returning what they held.","params":[{"name":"spawner_id","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"{ ItemHolder }\\n"}],"function_type":"method","source":{"line":632,"path":"src2/server/EmberServerLibrary/GameServer/Services/GroundItemService.service.luau"}},{"name":"GetAll","desc":"Every live pile. Copied out, so removal during iteration is safe.","params":[],"returns":[{"desc":"","lua_type":"{ GroundSpawn }\\n"}],"function_type":"method","source":{"line":649,"path":"src2/server/EmberServerLibrary/GameServer/Services/GroundItemService.service.luau"}},{"name":"Clear","desc":"Drop every pile. Used by tests and by a place teardown.","params":[],"returns":[],"function_type":"method","source":{"line":662,"path":"src2/server/EmberServerLibrary/GameServer/Services/GroundItemService.service.luau"}}],"properties":[],"types":[],"name":"GroundItemService","desc":"World piles, as holders.\\n\\nWHAT CHANGED\\n\\nThe old service ran a parallel item lifecycle beside the inventory one. A\\nground spawn owned an `Item` object, subscribed to its `OnUpdate` signal, and\\nmirrored quantity and durability onto a part attribute from inside that\\ncallback. Dropping had three branches -- merge into a nearby pile, clone the\\nitem for a partial drop, or move the whole object and clear the slot it came\\nfrom -- and each branch had to decide for itself whether the source slot was\\nnow empty.\\n\\nA ground pile is already an `ItemHolder` with `Unlimited` capacity, so all\\nthree branches are one `Transfer`. Conservation is the transfer\'s job:\\nwhatever does not fit stays in the source holder, because the source holder\\nstill exists. Nothing is cloned, nothing is destroyed to make an arithmetic\\nresult come out, and no slot has to be cleared as a side effect -- an emptied\\nholder is simply an empty holder.\\n\\nWhat is left here is the part the model does not cover: where a pile sits in\\nthe world, which cell it hashes to, and which part instance represents it.\\n\\nTESTABILITY\\n\\n`World` and `Schedule` are injectable seams, the same pattern\\n`ItemContextService` uses for `Schedule` and `HasPermission`. Both default to\\ndoing nothing, so every function below runs headless -- no `workspace`, no\\npart pool, no raycast. The Roblox-side implementation is installed at boot by\\n`GroundItemBinding`, which is the only piece that needs a running place.\\n\\nNO SESSION OBJECT\\n\\nRange checks take a `Player` and resolve the character through\\n`CharacterUtil`, which goes to CustomCharacter\'s PlayerList -- `Player.Character`\\nis NOT the authority in this game. Read fresh rather than cached, unlike the\\n`client.PrimaryPart` it replaces, which went stale across a respawn.\\nSee the convention note in `src2/PORT.md`.","source":{"line":44,"path":"src2/server/EmberServerLibrary/GameServer/Services/GroundItemService.service.luau"}}')}}]);